struct ToolGeometry {Scene*s;std::vector<guchar>before;const char*phase="external";unsigned n=0;void record(const char*event){g_print("EVENT %u phase=%s event=%s geometry=%d,%d,%d,%d pending=%d baseline_pixels=%d depth=%d\n",++n,phase,event,gimp_item_get_offset_x(GIMP_ITEM(s->drawable)),gimp_item_get_offset_y(GIMP_ITEM(s->drawable)),gimp_item_get_width(GIMP_ITEM(s->drawable)),gimp_item_get_height(GIMP_ITEM(s->drawable)),gimp_painter_mybrush_tool_has_pending_stroke(GIMP_PAINTER_MYBRUSH_TOOL(s->tool)),s->pixels()==before,s->depth());}};
static void tg_update(GimpDrawable*,gint,gint,gint,gint,gpointer p){static_cast<ToolGeometry*>(p)->record("update");}
static void tg_dirty(GimpImage*,GimpDirtyMask,gpointer p){static_cast<ToolGeometry*>(p)->record("dirty");}
static void tg_notify(GObject*,GParamSpec*s,gpointer p){static_cast<ToolGeometry*>(p)->record(s->name);}
static void tool_geometry(){Scene s;ToolGeometry p{&s,s.pixels()};s.motion(false);s.press();s.coords.x+=20;s.motion(true,75);auto u=g_signal_connect(s.drawable,"update",G_CALLBACK(tg_update),&p);auto n=g_signal_connect(s.drawable,"notify",G_CALLBACK(tg_notify),&p);auto dirty=g_signal_connect(s.image,"dirty",G_CALLBACK(tg_dirty),&p);const char*k=g_getenv("PROBE_KIND");g_print("CASE kind=%s\n",k);p.record("before-external");if(!strcmp(k,"grow")||!strcmp(k,"shrink"))gimp_item_resize(GIMP_ITEM(s.drawable),gimp_get_user_context(gimp),GIMP_FILL_TRANSPARENT,!strcmp(k,"grow")?144:80,!strcmp(k,"grow")?144:80,0,0);else if(!strcmp(k,"translate"))gimp_item_translate(GIMP_ITEM(s.drawable),4,3,TRUE);else if(!strcmp(k,"offset"))gimp_item_set_offset(GIMP_ITEM(s.drawable),4,3);else{auto*copy=gegl_buffer_dup(gimp_drawable_get_buffer(s.drawable));gimp_drawable_set_buffer(s.drawable,TRUE,nullptr,copy);g_object_unref(copy);}p.record("after-external");g_signal_handler_disconnect(s.drawable,u);g_signal_handler_disconnect(s.drawable,n);g_signal_handler_disconnect(s.image,dirty);}
int main(int argc,char**argv){g_test_init(&argc,&argv,nullptr);if(!gtk_init_check(&argc,&argv))return GIMP_EXIT_TEST_SKIPPED;gimp_test_utils_setup_menus_path();gimp=gimp_init_for_gui_testing(TRUE);g_object_set(gimp->config,"painter-canvas-ui",TRUE,nullptr);g_test_add_func("/geometry/tool",tool_geometry);g_application_run(gimp->app,0,nullptr);int result=gimp_core_app_get_exit_status(GIMP_CORE_APP(gimp->app));g_application_quit(G_APPLICATION(gimp->app));g_clear_object(&gimp->app);return result;}
